def _has_path(board: dict) -> bool:
    walls = {tuple(w) for w in board["walls"]}
    start = tuple(board["start"])
    goal = tuple(board["goal"])
    width = board["width"]
    height = board["height"]

    if start in walls or goal in walls:
        return False

    q = deque([start])
    seen = {start}
    while q:
        x, y = q.popleft()
        if (x, y) == goal:
            return True
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nxt = (x + dx, y + dy)
            if (
                0 <= nxt[0] < width
                and 0 <= nxt[1] < height
                and nxt not in walls
                and nxt not in seen
            ):
                seen.add(nxt)
                q.append(nxt)
    return False

